<?php

namespace App\Models;

use Illuminate\Database\Eloquent\Model;

/**
 * @property string $opaqueId URL key. CSPRNG, NOT a friendlyId: crypto.randomBytes(16) base64url.
 * Generated by the create path (deploy-sync / P2 API), NOT by @default.
 * @property string $declaredId The declared webhooks.endpoint.define id (string ref, no relation).
 * @property mixed $routingTargets Subscribers of this endpoint: StoredWebhookRoutingTarget[] ({ id, type: "task" | "session", ..., filterAst }).
 * @property string|null $setupPrompt The source's instructions for an AI agent registering this endpoint with the provider.
 * @property string|null $signingSecretKey SecretReference.key string. Plain String, NO @relation -> no FK to SecretReference.
 * @property \Carbon\CarbonInterface|null $manuallyDeactivatedAt When an operator disabled the endpoint via the dashboard/API. Null means the declarative sync
 * owns the status: a redeploy that re-declares a previously-removed (auto-deactivated) webhook
 * reactivates it. Non-null means the operator disabled it, so the sync leaves the status alone.
 */
class WebhookEndpoint extends Model
{
    use PrismaDates;

    const CREATED_AT = 'createdAt';
    const UPDATED_AT = 'updatedAt';

    protected $table = 'WebhookEndpoint';

    protected $keyType = 'string';

    public $incrementing = false;

    protected $fillable = [
        'id',
        'friendlyId',
        'opaqueId',
        'organizationId',
        'projectId',
        'runtimeEnvironmentId',
        'environmentType',
        'endpointTenantId',
        'endpointExternalRef',
        'source',
        'declaredId',
        'routingTargets',
        'verifierArtifact',
        'metadata',
        'secretProvisioning',
        'setupPrompt',
        'signingSecretKey',
        'status',
        'manuallyDeactivatedAt',
    ];

    protected $attributes = [
        'endpointTenantId' => '',
        'endpointExternalRef' => '',
        'routingTargets' => '[]',
        'metadata' => '{}',
        'secretProvisioning' => 'either',
        'status' => 'ACTIVE',
    ];

    protected $casts = [
        'environmentType' => RuntimeEnvironmentType::class,
        'routingTargets' => 'array',
        'verifierArtifact' => 'array',
        'metadata' => 'array',
        'status' => WebhookEndpointStatus::class,
        'manuallyDeactivatedAt' => 'datetime',
    ];
}